using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace GearLab {
 public static class RobotTransmission60Tests {
  public static int Run(string folder){Directory.CreateDirectory(folder);var checks=new List<string>();var fails=new List<string>();Action<bool,string> c=(ok,msg)=>{if(ok)checks.Add(msg);else fails.Add(msg);};try{for(int kind=5;kind<=12;kind++){var d=new RobotDocument();var j=d.Add(null);j.BodyStyle=RobotBodyStyle.Открытая_рама;j.BodyGenerator=null;j.ReducerSettings=Engine.Starter(kind);if(kind==12){j.Mode=RobotJointMode.Линейный_X;j.Minimum=-20;j.Maximum=20;j.Position=10;j.ScrewLead=Math.PI*j.ReducerSettings.Module*j.ReducerSettings.Teeth;}var r=Engine.Calculate(j.ReducerSettings);j.Reduction=r.Actual;j.Efficiency=r.Engineering.Efficiency;RobotTransmission60.ValidateJoint(j,r);var model=RobotCad.Build(d);c(model.Model.Valid,"robot embeds "+kind+": "+string.Join(";",model.Model.Errors));if(!model.Model.Valid)continue;var entries=model.Entries.Values.Where(e=>e.Category=="Передача").ToList();c(entries.Count>0,"actual transmission parts "+kind);c(entries.All(e=>e.Part.Volume()>0),"positive embedded volume "+kind);var analysis=RobotSolver.Solve(model);c(analysis.Valid,"robot loads "+kind);c(Math.Abs(analysis.TotalMass-model.Entries.Values.Sum(e=>model.Mass(e))-j.Payload)<1e-9,"all components counted once "+kind);if(kind==11)c(!analysis.Joints[0].Enough&&analysis.Joints[0].Message.Contains("FEA"),"magnetic capacity not invented");var posed=model.Pose(entries[0].Id,.1,true);c(posed.HasInverse,"embedded motion finite "+kind);var loaded=RobotDocument.Parse(d.Serialize());c(loaded.Joints[0].ReducerSettings.Kind==kind,"robot reducer serialization "+kind);if(kind==6)c(entries.Any(e=>e.Part.Loft!=null),"B-rep loft parameters survive robot copy");if(kind==12){var rack=entries.First(e=>e.Part.Label.Contains("рейка"));var p0=model.Current[j.Id];c(rack.Part.Placement.HasInverse,"linear placement");}}
   var doc=new RobotDocument();var joint=doc.Add(null);joint.BodyGenerator=null;joint.BodyStyle=RobotBodyStyle.Открытая_рама;var train=new TransmissionTrain();train.Stages.Add(new TrainStage{Parameters=Engine.Starter(6)});RobotTrainIntegration.Apply(joint,train,train.Stages[0].Id);var rb=RobotCad.Build(doc);c(rb.Model.Valid,"train robot embedding: "+string.Join(";",rb.Model.Errors));c(RobotSolver.Solve(rb).Valid,"train robot load integration");c(RobotDocument.Parse(doc.Serialize()).Joints[0].TrainSettings.Stages.Count==1,"train robot persistence");
  }catch(Exception ex){fails.Add(ex.ToString());}File.WriteAllText(Path.Combine(folder,"robot-transmission60-results.json"),CADDocument.Serializer().Serialize(new{Passed=fails.Count==0,Checks=checks.Count,Failures=fails}));return fails.Count==0?0:1;}
 }
}
